public static void main(Args _args)
{
    RMarketAccount account;
    Dialog dialog;
    DialogField dlgAccountId;
    RMarketAccountId accountId;

    dialog = new Dialog("Test exchange account binding");

    dlgAccountId = dialog.addFieldValue(extendedTypeStr(RMarketAccountId), 'DAT-ACC00011');

    if (dialog.run())
    {
        accountId = dlgAccountId.value();
        account = RMarketAccount::find(accountId);

        if (!account.RecId)
            throw error("Account not found.");

        account.bindExchangeAccount();

        account = RMarketAccount::find(accountId);

        info(strFmt("Account binding PASS: %1 -> %2",
            account.AccountId,
            account.ExchangeUid));
    }
}
